import json
from pathlib import Path
from re import compile

# Local-fallback answer-asset verification per meta/asset_types/answer/specification.md v2
asset_dir = Path('tasks/t0121_5seed_substrate_rate_canonical_report/assets/answer/substrate-rate-5seed-canonical')
errors = []
warnings = []

# AA-E001: details.json exists and valid JSON
details_path = asset_dir / 'details.json'
if not details_path.exists():
    errors.append('AA-E001: details.json missing')
else:
    try:
        details = json.loads(details_path.read_text(encoding='utf-8'))
    except Exception as e:
        errors.append(f'AA-E001: details.json invalid JSON: {e}')
        details = None

# AA-E002: canonical answer documents present
for fname in ['short_answer.md', 'full_answer.md']:
    if not (asset_dir / fname).exists():
        errors.append(f'AA-E002: {fname} missing')

# AA-E003: answer_id matches folder name
if details and details.get('answer_id') != asset_dir.name:
    errors.append(f'AA-E003: answer_id mismatch')

# AA-E004: answer_id format
slug_re = compile(r'^[a-z0-9]+(-[a-z0-9]+)*$')
if details and not slug_re.match(details.get('answer_id', '')):
    errors.append('AA-E004: answer_id format invalid')

# AA-E005: required fields present
required_fields = {'spec_version','answer_id','question','short_title','short_answer_path','full_answer_path','categories','answer_methods','source_paper_ids','source_urls','source_task_ids','confidence','created_by_task','date_created'}
if details:
    missing = required_fields - set(details.keys())
    if missing:
        errors.append(f'AA-E005: missing fields: {missing}')

# AA-E006: answer_methods allowed values
allowed_methods = {'papers','internet','code-experiment','prior-task'}
if details:
    for m in details.get('answer_methods', []):
        if m not in allowed_methods:
            errors.append(f'AA-E006: unknown answer_method {m}')

# AA-E007: confidence
if details and details.get('confidence') not in {'high','medium','low'}:
    errors.append('AA-E007: confidence not allowed value')

# AA-E014: at least one evidence
if details:
    evidence_total = len(details.get('source_paper_ids', [])) + len(details.get('source_urls', [])) + len(details.get('source_task_ids', []))
    if evidence_total == 0:
        errors.append('AA-E014: no evidence references')

# AA-E011/12: mandatory sections present
short_required = ['## Question', '## Answer', '## Sources']
full_required = ['## Question','## Short Answer','## Research Process','## Evidence from Papers','## Evidence from Internet Sources','## Evidence from Code or Experiments','## Synthesis','## Limitations','## Sources']

short_text = (asset_dir / 'short_answer.md').read_text(encoding='utf-8')
for h in short_required:
    if h not in short_text:
        errors.append(f'AA-E011: short_answer.md missing section {h!r}')

full_text = (asset_dir / 'full_answer.md').read_text(encoding='utf-8')
for h in full_required:
    if h not in full_text:
        errors.append(f'AA-E012: full_answer.md missing section {h!r}')

# AA-E013: short ## Answer is 2-5 sentences
import re
m = re.search(r'## Answer\n(.*?)(?=\n## |\Z)', short_text, re.DOTALL)
if m:
    answer_block = m.group(1).strip()
    sentences = re.split(r'(?<=[.!?])\s+', answer_block)
    sentences = [s for s in sentences if s.strip()]
    if not (2 <= len(sentences) <= 5):
        errors.append(f'AA-E013: ## Answer has {len(sentences)} sentences (need 2-5)')

# AA-W004: full answer length
full_word_count = len(full_text.split())
if full_word_count < 500:
    warnings.append(f'AA-W004: full_answer.md only {full_word_count} words')

print('Errors:', len(errors))
for e in errors: print(' ', e)
print('Warnings:', len(warnings))
for w in warnings: print(' ', w)
